pid_t target_pid = 0; // Query calling thread
cpu_set_t current_mask;
int result;

CPU_ZERO(&current_mask);

// Get the current affinity mask
result = sched_getaffinity(
    target_pid,
    sizeof(cpu_set_t),
    &current_mask
);

// Check if CPU 1 is included in the mask
if (result == 0) {
    int is_cpu_1_eligible = CPU_ISSET(1, &current_mask);
}
